'use client';

// Import THREE.js library for geometry manipulation
import * as THREE from 'three';

// Component function - extracts and visualizes vertices from a cylinder
function VerticesScene() {
  // Step 1: Create a cylinder geometry (same as IntroScene)
  const geometry = new THREE.CylinderGeometry(0.6, 0.6, 2, 32);

  // Step 2: Extract the position data (vertex coordinates)
  // geometry.attributes.position contains all vertex positions
  // .array gives us the raw Float32Array: [x1, y1, z1, x2, y2, z2, ...]
  const positions = geometry.attributes.position.array;

  // Step 3: Create a new BufferGeometry to hold just the vertices
  const bufferGeometry = new THREE.BufferGeometry();

  // Step 4: Set the position attribute
  // Float32BufferAttribute(positions, 3) means:
  //   - positions: the array of coordinates
  //   - 3: each vertex has 3 components (x, y, z)
  bufferGeometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));

  // Step 5: Clean up the original geometry to free memory
  geometry.dispose();

  // Render vertices as points
  return (
    <points geometry={bufferGeometry}>
      {/* pointsMaterial controls how points are rendered
          size: size of each point in world units (0.05 = small)
          color: hex color string
          sizeAttenuation: if true, points get smaller with distance (perspective) */}
      <pointsMaterial 
        size={0.05}
        color="#10b981"
        sizeAttenuation
      />
    </points>
  );
}

