// Import Edges component from @react-three/drei
// drei is a collection of useful helpers for R3F
import { Edges } from '@react-three/drei';
// Import THREE for geometry creation
import * as THREE from 'three';

// Component function - visualizes edges (wireframe) of a cylinder
function EdgesScene() {
  // Create cylinder geometry using THREE.js directly
  // This gives us more control than using <cylinderGeometry>
  const canGeometry = new THREE.CylinderGeometry(0.6, 0.6, 2, 32);

  return (
    <mesh geometry={canGeometry}>
      {/* meshBasicMaterial with transparent opacity={0}
          This makes the surface invisible so we only see the edges
          transparent: must be true for opacity to work
          opacity: 0 = completely invisible */}
      <meshBasicMaterial transparent opacity={0} />

      {/* Edges component from drei renders the wireframe
          It automatically detects edges from the geometry
          color: hex color string for the edge lines
          threshold: angle threshold in radians for edge detection
                    0 = show all edges (sharp edges only)
                    Higher values = show more edges (including smooth curves) */}
      <Edges color="#3b82f6" threshold={0} />
    </mesh>
  );
}

'use client';

// Import Edges component from @react-three/drei
import { Edges } from '@react-three/drei';
// Import THREE for geometry creation
import * as THREE from 'three';

// Component function - combines faces (surface) with edges (wireframe)
function FacesScene() {
  // Create the main geometry for the surface
  const canGeometry = new THREE.CylinderGeometry(0.6, 0.6, 2, 32);

  // Create a separate EdgesGeometry for the wireframe
  // EdgesGeometry is a THREE.js class that extracts edges from geometry
  const baseGeometry = new THREE.CylinderGeometry(0.6, 0.6, 2, 32);
  const edgesGeometry = new THREE.EdgesGeometry(baseGeometry);

  return (
    <mesh geometry={canGeometry}>
      {/* meshStandardMaterial renders the surface (faces)
          This material responds to lighting and shows the 3D shape
          color: base color of the material
          metalness: 0.8 = very metallic
          roughness: 0.2 = very smooth, polished surface */}
      <meshStandardMaterial
        color="#14b8a6"
        metalness={0.8}
        roughness={0.2}
      />

      {/* Edges component overlays wireframe on top of the material
          geometry: explicitly pass the EdgesGeometry we created
          color: black wireframe lines
          threshold: 0 = only show sharp edges
          This shows both the surface (faces) and the structure (edges) */}
      <Edges geometry={edgesGeometry} color="#000000" threshold={0} />
    </mesh>
  );
}

