function R3FBasicsScene() {
  return (
    <mesh 
      // position: [x, y, z] - moves the mesh in 3D space
      // [1, 0, 0] = 1 unit to the right, 0 up/down, 0 forward/back
      position={[1, 0, 0]}

      // rotation: [x, y, z] - rotates around each axis in radians
      // [0, Math.PI / 4, 0] = rotate 45° around Y axis (vertical)
      // Math.PI / 4 = 45 degrees (Math.PI = 180°)
      rotation={[0, Math.PI / 4, 0]}
    >
      {/* boxGeometry defines a rectangular box
          args: [width, height, depth]
          [2, 2, 2] = a cube that's 2 units in each dimension */}
      <boxGeometry args={[2, 2, 2]} />

      {/* meshStandardMaterial defines how the surface looks
          color: can be a named color string or hex
          'hotpink' is a CSS named color
          This material responds to lighting in the scene */}
      <meshStandardMaterial color="hotpink" />
    </mesh>
  );
}

