'use client';

// Import useTexture hook from @react-three/drei
// drei is a collection of useful helpers for R3F
import { useTexture } from '@react-three/drei';

// Component function - demonstrates different material types
function R3FMaterialsScene({ texturePath }: { texturePath: string }) {
  // useTexture is a hook that loads an image file as a texture
  // It handles loading, caching, and returns a THREE.Texture object
  // texturePath: string path to the image file (e.g., '/texture.jpg')
  // The hook automatically handles async loading and updates when path changes
  const texture = useTexture(texturePath);

  return (
    <group>
      {/* Basic material - flat color, no lighting
          meshBasicMaterial ignores all lights in the scene
          It always shows the same color regardless of lighting
          Useful for UI elements or unlit objects */}
      <mesh position={[-2, 0, 0]}>
        <boxGeometry args={[1, 1, 1]} />
        <meshBasicMaterial color="#3b82f6" />
      </mesh>

      {/* Standard material with metallic properties
          meshStandardMaterial responds to lighting
          color: base color (can be a named color like 'gold')
          metalness: 0-1, how metallic (0.8 = very metallic, like gold)
          roughness: 0-1, how smooth (0.2 = very smooth, polished) */}
      <mesh position={[0, 0, 0]}>
        <boxGeometry args={[1, 1, 1]} />
        <meshStandardMaterial
          color="gold"
          metalness={0.8}
          roughness={0.2}
        />
      </mesh>

      {/* Standard material with texture
          map: applies the texture loaded with useTexture
          The texture is applied on top of the base color
          The texture will be stretched to cover the entire surface
          color: still affects the final appearance (tints the texture) */}
      <mesh position={[2, 0, 0]}>
        <boxGeometry args={[1, 1, 1]} />
        <meshStandardMaterial
          color="#8b5cf6"
          metalness={0.7}
          roughness={0.3}
          map={texture}
        />
      </mesh>
    </group>
  );
}

