// Component function - a complete scene with geometry, material, and lighting
function R3FFirstScene() {
  return (
    {/* Fragment (<>...</>) groups multiple elements without adding a DOM node
        In R3F, this groups multiple 3D objects in the scene */}
    <>
      {/* The 3D object - a simple cube
          No position = centered at origin [0, 0, 0]
          args: [width, height, depth] = [2, 2, 2] = a 2x2x2 cube */}
      <mesh>
        <boxGeometry args={[2, 2, 2]} />
        {/* meshStandardMaterial with no props = default white material
            It will respond to lighting in the scene */}
        <meshStandardMaterial />
      </mesh>

      {/* Ambient light - soft overall illumination
          Provides base lighting to all objects equally
          Prevents pure black shadows (adds a base brightness)
          intensity: 0-1, how bright (0.1 = dim, prevents total darkness)
          Ambient light has no direction - it lights everything equally */}
      <ambientLight intensity={0.1} />

      {/* Directional light - like sunlight
          Shines from a specific direction, creates shadows and highlights
          position: [x, y, z] - direction the light comes from
                     [0, 0, 5] = light comes from in front (positive Z)
          color: color of the light ('red' = red-tinted light)
          intensity: 0-1, how bright (0.8 = quite bright)
          Directional lights create realistic lighting with highlights and shadows */}
      <directionalLight 
        position={[0, 0, 5]}
        color="red"
        intensity={0.8}
      />
    </>
  );
}

'use client';

// Import hooks from @react-three/drei for loading 3D models and textures
// drei is a collection of useful helpers for R3F
import { useGLTF, useTexture } from '@react-three/drei';
// Import THREE for type checking and material manipulation
import * as THREE from 'three';
// Import React hooks for side effects
import { useLayoutEffect } from 'react';

// Component function - loads and displays a 3D model with texture
function ShowcaseScene({ texturePath }: { texturePath: string }) {
  // useGLTF loads a GLTF/GLB 3D model file
  // GLTF is a standard format for 3D models (like JPEG for images)
  // Returns an object with:
  //   - scene: the root THREE.Group containing the entire model
  //   - materials: (optional) a record of material names to THREE.Material objects
  // The hook handles async loading, caching, and updates when path changes
  const { scene, materials } = useGLTF('/beer2.gltf') as {
    scene: THREE.Group;
    materials?: Record<string, THREE.Material>;
  };

  // useTexture loads an image file as a texture
  // texturePath: string path to the image file (e.g., '/texture.jpg')
  // Returns a THREE.Texture object that can be applied to materials
  // The hook handles async loading, caching, and updates when path changes
  const texture = useTexture(texturePath);

  // useLayoutEffect runs synchronously after DOM mutations but before paint
  // Perfect for applying textures to materials (needs to happen before render)
  useLayoutEffect(() => {
    if (!texture) return;

    // Configure texture settings
    texture.flipY = false; // Fix upside down texture (WebGL vs image coordinate systems)

    // Apply texture to materials by traversing the scene
    // scene.traverse() visits every object in the scene tree
    scene.traverse(obj => {
      // Check if this object is a mesh with a material
      if (obj instanceof THREE.Mesh && obj.material) {
        const material = obj.material;

        // Handle both single materials and material arrays
        if (material instanceof THREE.MeshStandardMaterial) {
          // Apply texture to the material
          material.map = texture;
          // Tell Three.js the material needs to be updated
          material.needsUpdate = true;
        }
      }
    });
  }, [scene, texture]); // Re-run when scene or texture changes

  // Render the 3D model
  return (
    <group>
      {/* primitive component allows you to render any Three.js object
          object: the Three.js object to render (the loaded scene)
          dispose={null} prevents R3F from disposing the geometry when unmounting
          (useful if you want to keep the model in memory for reuse) */}
      <primitive object={scene} dispose={null} />
    </group>
  );
}
